import XCTest
@testable import MirNavigation
final class PeerInspectionTests:XCTestCase {
    private var captured:[UInt8] {
        let hex=""
        return stride(from:0,to:hex.count,by:2).map { i in
            let start=hex.index(hex.startIndex,offsetBy:i)
            return UInt8(hex[start..<hex.index(start,offsetBy:2)],radix:16)!
        }
    }
    func testCapturedEquipment() throws {
        let state=try XCTUnwrap(MirPeerInspection.decode(captured))
        XCTAssertEqual(String(decoding:state.name,as:UTF8.self),"WeaponCheck13")
        XCTAssertEqual(state.equipment[1]?.id,2100010213)
        XCTAssertEqual(state.equipment.count,1)
    }
    func testRejectTruncationAndInvalidNames() {
        XCTAssertNil(MirPeerInspection.decode(Array(captured.dropLast())))
        XCTAssertNil(MirPeerInspection.decode(captured+[0]))
        for offset in [4,24,45,184] {
            var bytes=captured;bytes[offset]=255
            XCTAssertNil(MirPeerInspection.decode(bytes))
        }
    }
}
